import{_ as e,o as r,c as o,a2 as d}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse('{"title":"Comparison: OpenShield-XDP vs Alternatives","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/reference/comparison.md","filePath":"openshield-xdp/reference/comparison.md","lastUpdated":1783153244000}'),a={name:"openshield-xdp/reference/comparison.md"};function n(s,t,i,l,c,p){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="comparison-openshield-xdp-vs-alternatives" tabindex="-1">Comparison: OpenShield-XDP vs Alternatives <a class="header-anchor" href="#comparison-openshield-xdp-vs-alternatives" aria-label="Permalink to &quot;Comparison: OpenShield-XDP vs Alternatives&quot;">​</a></h1><h2 id="vs-raw-iptables-nftables" tabindex="-1">vs raw iptables / nftables <a class="header-anchor" href="#vs-raw-iptables-nftables" aria-label="Permalink to &quot;vs raw iptables / nftables&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>iptables / nftables</th><th>OpenShield-XDP</th></tr></thead><tbody><tr><td><strong>Where it runs</strong></td><td>Kernel netfilter (after skb allocation)</td><td>NIC driver XDP hook (before skb allocation)</td></tr><tr><td><strong>Throughput</strong></td><td>~1-3 Mpps per core</td><td><strong>10M+ pps</strong> per core</td></tr><tr><td><strong>CPU cost</strong></td><td>Per-packet context switch + skb alloc overhead</td><td>Zero-copy, no context switch — DMA ring direct access</td></tr><tr><td><strong>DDoS resistance</strong></td><td>Connection tracking table fills → kernel OOM</td><td>Drops at wire speed, kernel never sees the attack traffic</td></tr><tr><td><strong>State model</strong></td><td><code>conntrack</code> table (limited, global)</td><td>Per-IP LRU map (100K entries, auto-eviction, no global bottleneck)</td></tr><tr><td><strong>Configuration</strong></td><td>Thousands of rules, fragile ordering</td><td>One YAML file, 34 thresholds, 70 presets</td></tr><tr><td><strong>Zero-tune setup</strong></td><td>No</td><td>Yes — workload-based profile recommendation</td></tr></tbody></table><h2 id="vs-xdp-firewall-gamemann" tabindex="-1">vs XDP-Firewall (Gamemann) <a class="header-anchor" href="#vs-xdp-firewall-gamemann" aria-label="Permalink to &quot;vs XDP-Firewall (Gamemann)&quot;">​</a></h2><p><a href="https://github.com/gamemann/XDP-Firewall" target="_blank" rel="noreferrer">XDP-Firewall</a> is a popular open-source XDP firewall written in C with libconfig. It&#39;s solid for basic IP/port filtering.</p><table tabindex="0"><thead><tr><th></th><th>XDP-Firewall</th><th>OpenShield-XDP</th></tr></thead><tbody><tr><td><strong>Detection vectors</strong></td><td>~5 (IP/port allow/deny, basic rate limiting)</td><td><strong>42</strong> across L2-L7</td></tr><tr><td><strong>DDoS mitigation</strong></td><td>Simple PPS rate limiting per IP</td><td>Suspicion scoring, token bucket, L7 pattern matching, entropy spoofing, UDP amplification detection, blind SYN-ACK/RST, TTL anomaly, packet size anomaly</td></tr><tr><td><strong>SYN flood</strong></td><td>Basic SYN rate limit</td><td>Scalar rate-based SYN gate + per-IP <code>syn_pps_threshold</code> — no cookies, loads on all kernels</td></tr><tr><td><strong>Auto-config</strong></td><td>Manual config only</td><td><strong>10 profiles × 7 levels</strong> — workload-based recommendations</td></tr><tr><td><strong>Kernel portability</strong></td><td>Needs per-kernel adjustments for verifier</td><td>Loads on 5.15 → latest with zero fixes — auto-generated vmlinux.h, scalar-only SYNPROXY</td></tr><tr><td><strong>Userspace</strong></td><td>C + libconfig</td><td>Go + cilium/ebpf, embedded BPF, no external library dependencies</td></tr><tr><td><strong>Hot-patching</strong></td><td>No</td><td>Opt-in freplace (kernel ≥6.10) — swap mitigation stages without unloading XDP</td></tr><tr><td><strong>Subnet auto-ban</strong></td><td>No</td><td>Auto-bans /24 subnets when multiple IPs in same prefix are banned</td></tr><tr><td><strong>Bloom filter</strong></td><td>No</td><td>150K-entry Bloom filter for fast whitelist negative-check (~60-100ns saved per lookup)</td></tr><tr><td><strong>TUI dashboard</strong></td><td>No</td><td>7-screen real-time dashboard with braille-resolution charts, config editor</td></tr><tr><td><strong>Webhook alerts</strong></td><td>No</td><td>Discord/Slack alerts on bans, attacks, config changes</td></tr></tbody></table><h2 id="vs-xdp-filter-xdp-tools" tabindex="-1">vs xdp-filter (xdp-tools) <a class="header-anchor" href="#vs-xdp-filter-xdp-tools" aria-label="Permalink to &quot;vs xdp-filter (xdp-tools)&quot;">​</a></h2><p><a href="https://github.com/xdp-project/xdp-tools" target="_blank" rel="noreferrer">xdp-filter</a> is part of the official xdp-tools suite from the Linux kernel community. It&#39;s an ACL — allow/deny by IP, MAC, port, or protocol.</p><table tabindex="0"><thead><tr><th></th><th>xdp-filter</th><th>OpenShield-XDP</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Access control (allow/deny list)</td><td>DDoS mitigation + access control</td></tr><tr><td><strong>Attack detection</strong></td><td>None — it&#39;s a static filter</td><td>42 detection vectors with dynamic scoring and auto-ban</td></tr><tr><td><strong>Rate limiting</strong></td><td>No</td><td>Per-IP PPS/BPS, per-protocol, token bucket</td></tr><tr><td><strong>Behavioral detection</strong></td><td>No</td><td>Entropy, SYN/FIN ratio, TTL, packet size anomalies</td></tr><tr><td><strong>Amplification detection</strong></td><td>No</td><td>DNS + 8-port generic UDP reflection</td></tr><tr><td><strong>L7 filtering</strong></td><td>No</td><td>16-slot byte-pattern matching with configurable offset/mask</td></tr><tr><td><strong>Configuration</strong></td><td>CLI flags per rule</td><td>YAML + interactive CLI wizard + 70 presets</td></tr><tr><td><strong>Installation</strong></td><td>Distribution package</td><td>One-line curl installer, auto-detects kernel features</td></tr></tbody></table><p>xdp-filter is the right tool if you need a simple &quot;allow these IPs, drop everything else&quot; rule at XDP speed. OpenShield is for DDoS protection — it identifies and blocks attack patterns automatically.</p><h2 id="vs-kernel-synproxy-tcp-syncookies" tabindex="-1">vs kernel SYNPROXY (<code>tcp_syncookies</code>) <a class="header-anchor" href="#vs-kernel-synproxy-tcp-syncookies" aria-label="Permalink to &quot;vs kernel SYNPROXY (`tcp_syncookies`)&quot;">​</a></h2><p>Linux&#39;s built-in SYN cookie mechanism (<code>sysctl net.ipv4.tcp_syncookies=1</code>) is defense-in-depth that runs inside the kernel TCP stack. OpenShield&#39;s SYN gate runs at XDP, earlier in the pipeline.</p><table tabindex="0"><thead><tr><th></th><th>Kernel <code>tcp_syncookies</code></th><th>OpenShield SYNPROXY</th></tr></thead><tbody><tr><td><strong>Runs at</strong></td><td>TCP stack (after XDP, after skb alloc)</td><td>XDP — before kernel sees the packet</td></tr><tr><td><strong>Drops SYNs</strong></td><td>No — responds with SYN-ACK cookies</td><td>Rate-limits per source IP directly</td></tr><tr><td><strong>Protects connection table</strong></td><td>Eventually (table can still fill before cookie exchange)</td><td>Immediately — SYN flood sources are banned before conntrack is touched</td></tr><tr><td><strong>CPU cost</strong></td><td>Cookie generation + TCP processing overhead</td><td>~30 BPF instructions (scalar comparison)</td></tr><tr><td><strong>Recommended</strong></td><td>Always enable as a second layer</td><td>Primary SYN flood defense at line rate</td></tr></tbody></table><p><strong>Enable both.</strong> OpenShield handles the volumetric attack at XDP; <code>tcp_syncookies</code> handles whatever gets through as a safety net.</p><h2 id="vs-commercial-ddos-protection-cloudflare-akamai-voxility-path-net" tabindex="-1">vs commercial DDoS protection (Cloudflare, Akamai, Voxility, Path.net) <a class="header-anchor" href="#vs-commercial-ddos-protection-cloudflare-akamai-voxility-path-net" aria-label="Permalink to &quot;vs commercial DDoS protection (Cloudflare, Akamai, Voxility, Path.net)&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Commercial scrubbing</th><th>OpenShield-XDP</th></tr></thead><tbody><tr><td><strong>Cost</strong></td><td>$2,000 – $20,000+/month</td><td><strong>Free</strong> (GPL-2.0)</td></tr><tr><td><strong>Latency</strong></td><td>+1-10ms (BGP redirection to scrub center)</td><td><strong>0ms</strong> (runs on your NIC)</td></tr><tr><td><strong>Throughput cap</strong></td><td>Limited by scrub center capacity</td><td>Limited by your NIC hardware (~10 Mpps/core)</td></tr><tr><td><strong>Volumetric floods (&gt;10 Gbps)</strong></td><td>✅ Handled upstream</td><td>❌ Your uplink saturates before XDP runs</td></tr><tr><td><strong>Application-layer attacks</strong></td><td>Signature-based (delayed)</td><td>L7 pattern matching at line rate (instant)</td></tr><tr><td><strong>Setup time</strong></td><td>Days (BGP announcement + configuration)</td><td><strong>≈60 seconds</strong> (curl</td></tr><tr><td><strong>Privacy</strong></td><td>All traffic routed through third party</td><td>All traffic stays on your server</td></tr></tbody></table><p><strong>The right strategy:</strong> Use OpenShield for everything below your uplink capacity. For floods that exceed your bandwidth, you still need upstream filtering (ISP null-routing or a commercial scrubber). But OpenShield eliminates the need for a paid service for <strong>99% of attacks</strong> — the vast majority of DDoS attacks are well under 10 Gbps.</p><h2 id="when-to-use-what" tabindex="-1">When to use what <a class="header-anchor" href="#when-to-use-what" aria-label="Permalink to &quot;When to use what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your scenario</th><th>Recommendation</th></tr></thead><tbody><tr><td>Simple IP allow/deny at wire speed</td><td>xdp-filter</td></tr><tr><td>Basic port/IP filtering with some rate limiting</td><td>XDP-Firewall (Gamemann)</td></tr><tr><td><strong>Full DDoS protection with zero-tune setup</strong></td><td><strong>OpenShield-XDP</strong></td></tr><tr><td>&gt;10 Gbps sustained volumetric floods</td><td>ISP null-routing + commercial scrubber</td></tr><tr><td>Defense-in-depth (all of the above)</td><td>OpenShield at XDP + kernel <code>tcp_syncookies</code> + fail2ban at application layer</td></tr></tbody></table>',19)])])}const u=e(a,[["render",n]]);export{g as __pageData,u as default};
